window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[68]={"id":"068","numero":68,"titre":"Troubles du comportement de l'enfant et de l'adolescent","objectifs":[{"id":"68-1","rang":"A","rubrique":"Définition","titre":"Connaître les caractéristiques de l’adolescence normale","contenu":"<p>L'<strong><span class=\"kw-def\">adolescence</span></strong> est une période de <span class=\"kw-def\">maturation individuelle et sociale</span> liée à un contexte social. Ses contours sont <strong>mal définis et évolutifs</strong> : l'âge d'accès à l'autonomie ne cesse de s'accroître. <span class=\"kw-clinique\">Les</span> modifications observées sont la résultante de multiples facteurs <span class=\"kw-etio\">biologiques</span>, <span class=\"kw-etio\">psycho-affectifs</span> et <span class=\"kw-etio\">sociaux</span>.</p>\n      <p><strong>Principaux changements de l'adolescence :</strong></p>\n      <ul>\n        <li>Développement de l'<span class=\"kw-clinique\">autonomie</span> et des contacts sociaux, avec une <strong>influence accrue du groupe des pairs</strong>.</li>\n        <li>Recherche d'<span class=\"kw-clinique\">identité</span> et de valeurs, développement de la personnalité.</li>\n        <li>Modifications du <span class=\"kw-clinique\">désir sexuel</span> et du rapport au corps : préoccupations fréquentes sur l'apparence physique ; marques du corps fréquentes (tatouages, piercings).</li>\n        <li><span class=\"kw-clinique\">Hypersensibilité émotionnelle</span> et <span class=\"kw-clinique\">sensibilité au rejet</span>.</li>\n        <li>Expérimentation, augmentation des <span class=\"kw-clinique\">choix risqués</span>, moindre sensibilité aux conséquences à long terme des actions.</li>\n      </ul>\n      <p>Cette période repose sur une <strong><span class=\"kw-def\">neuro-plasticité</span></strong> importante : la maturation cérébrale se fait de façon <strong>différentielle</strong>.</p>\n      <table >\n        <thead><tr><th>Structure</th><th>Fonction</th><th>Maturation</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Système limbique</span></td><td>Sensibilité à la <span class=\"kw-clinique\">récompense</span>, réactivité émotionnelle</td><td><strong>Plus rapide</strong></td></tr>\n          <tr><td><span class=\"kw-def\">Cortex préfrontal</span></td><td>Contrôle, inhibition, anticipation des conséquences</td><td><strong>Plus tardive</strong></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Point clé EDN.</strong> Le décalage de maturation — limbique précoce <span class=\"kw-bio\">vs</span> préfrontal tardif — explique la <span class=\"kw-clinique\">prise de risque</span> et l'<span class=\"kw-clinique\">impulsivité</span> physiologiques de l'adolescent. L'adolescence sollicite des facultés d'<span class=\"kw-clinique\">adaptation</span> cognitive et émotionnelle particulièrement importantes.</div>\n      <p>Certains <span class=\"kw-def\">troubles mentaux</span> débutent habituellement à l'adolescence ou y voient leur <span class=\"kw-def\">prévalence</span> augmenter : <span class=\"kw-etio\">troubles schizophréniques</span>, <span class=\"kw-etio\">troubles de l'humeur</span>, certains <span class=\"kw-etio\">troubles des conduites alimentaires</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 63 — Trouble schizophrénique · 64 — <span class=\"kw-etio\">Trouble bipolaire</span> · 71 — Troubles conduite alimentaire</em></p>","frequence":0},{"id":"68-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition des troubles du comportement de l’enfant et de l’adolescent","contenu":"<p><span class=\"kw-clinique\">Les</span> <strong><span class=\"kw-def\">troubles du comportement</span></strong> de l'enfant et de l'adolescent — aussi appelés <strong><span class=\"kw-def\">troubles externalisés</span></strong> — recouvrent <strong>deux entités</strong> :</p>\n      <ul>\n        <li>le <strong><span class=\"kw-etio\">trouble oppositionnel avec provocation (TOP)</span></strong> ;</li>\n        <li>le <strong><span class=\"kw-etio\">trouble des conduites (TC)</span></strong>.</li>\n      </ul>\n      <p>Ils se caractérisent par des comportements perturbateurs dirigés vers l'<strong>extérieur</strong> (opposition, provocation, agression, <span class=\"kw-clinique\">transgression</span>), par opposition aux <span class=\"kw-def\">troubles internalisés</span> (<span class=\"kw-etio\">anxiété</span>, <span class=\"kw-etio\">dépression</span>).</p>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> <span class=\"kw-clinique\">Les</span> troubles du comportement doivent être <strong>distingués des troubles du comportement transitoires</strong> survenant en contexte de <span class=\"kw-etio\">stress</span>. Un comportement perturbateur réactionnel et passager n'est pas un trouble externalisé constitué.</div>","frequence":0},{"id":"68-3","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les facteurs de risque","contenu":"<p><span class=\"kw-clinique\">Les</span> troubles du comportement de l'enfant et de l'adolescent ont une origine <strong><span class=\"kw-etio\">multi-factorielle</span></strong>. Cinq familles de <span class=\"kw-def\">facteurs de risque</span> s'intriquent :</p>\n      <table >\n        <thead><tr><th>Famille</th><th>Facteurs de risque</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Génétiques</span></td>\n            <td>Agrégation familiale du TOP et du TC (<span class=\"kw-chiffre\">héritabilité 35-60 %</span>) ; interactions gènes-environnement contribuant au risque de troubles du comportement.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Neurobiologiques</span></td>\n            <td>Anomalies de l'activation de certaines zones corticales et limbiques impliquées dans le <span class=\"kw-clinique\">déficit d'inhibition</span> et <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">anomalies de la réponse au danger</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Neuro-physiologiques</span></td>\n            <td>\n              <strong>Faible réactivité au stress :</strong> moindre réactivité du rythme cardiaque ; faible réponse du cortisol à l'exposition au stress ; anomalies de la réactivité du système nerveux autonome<br>\n              <strong>Émotions :</strong> moindre ressenti de la <span class=\"kw-clinique\">peur</span>, de la <span class=\"kw-clinique\">honte</span> et de la <span class=\"kw-clinique\">culpabilité</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Cognitifs</span></td>\n            <td>\n              <strong>Biais d'attribution hostile :</strong> attribution d'intentions négatives à autrui dans des interactions neutres &rarr; <span class=\"kw-alerte\">légitimation de la violence</span><br>\n              <strong>Déficits :</strong> compréhension et expression verbale ; fonctionnement exécutif (inhibition, planification, organisation des actions).\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Environnementaux</span></td>\n            <td>\n              <strong>Périnataux :</strong> complications obstétricales ; faible poids de naissance ; exposition au <span class=\"kw-etio\">tabac</span> ou à l'<span class=\"kw-etio\">alcool</span> in utero<br>\n              <strong>Familiaux :</strong> style éducatif coercitif ou inconsistant (violences physiques/psychologiques, négligences éducatives) ; attachement désorganisé ; psychopathologie parentale (personnalité antisociale, abus de substances)<br>\n              <strong>Sociaux :</strong> exposition à la <span class=\"kw-alerte\">violence intra-familiale</span> ; environnement criminogène ; affiliation à un groupe de pairs déviants.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 57 — Maltraitance, enfant en danger · 66 — Trouble de la personnalité</em></p>","frequence":0},{"id":"68-4","rang":"A","rubrique":"Diagnostic","titre":"Connaître le diagnostic positif des troubles du comportement de l’enfant et de l’adolescent","contenu":"<p>Le diagnostic des troubles du comportement repose <strong>exclusivement sur des <span class=\"kw-def\">critères cliniques</span></strong>. Il distingue le <span class=\"kw-etio\">TOP</span> et le <span class=\"kw-etio\">TC</span>, qui doivent eux-mêmes être différenciés des troubles transitoires liés à un contexte de stress.</p>\n      <p><strong>Démarche diagnostique commune :</strong></p>\n      <ul>\n        <li><strong>Histoire :</strong> reconstituer l'histoire développementale du patient.</li>\n        <li><strong>Symptomatologie :</strong> passée et actuelle, ne correspondant pas au développement normal attendu. <strong>Plusieurs sources d'information</strong> sont nécessaires : parents, personnes en <span class=\"kw-def\">contact</span> avec l'enfant (professeurs, éducateurs) et l'enfant/adolescent lui-même.</li>\n        <li><strong>Retentissement :</strong> dans la plupart des domaines de vie — <span class=\"kw-chiffre\">&ge; 2 domaines</span> parmi familial, scolaire, activités extra-scolaires, social.</li>\n        <li><strong>Durée :</strong> trouble évoluant depuis <span class=\"kw-chiffre\">&gt; 6 mois</span>.</li>\n        <li><strong>Âge de début :</strong> pendant l'enfance ou l'adolescence.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> L'<span class=\"kw-alerte\">auto-évaluation par l'enfant n'est pas toujours fiable</span> pour <span class=\"kw-clinique\">les</span> symptômes de TOP/TC : <span class=\"kw-ci\">ne jamais</span> s'y limiter. Les tests psychométriques (attention, QI), bilans de personnalité et questionnaires apportent des arguments supplémentaires mais ne sont <strong>pas indispensables</strong> au diagnostic.</div>\n      <p><strong>Comparaison des deux entités :</strong></p>\n      <table >\n        <thead><tr><th>Caractéristique</th><th>TOP — trouble oppositionnel avec provocation</th><th>TC — trouble des conduites</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Prévalence</span></td>\n            <td><span class=\"kw-chiffre\">3 %</span></td>\n            <td><span class=\"kw-chiffre\">1,5 %</span></td>\n          </tr>\n          <tr>\n            <td>Sex-ratio</td>\n            <td>Légère prédominance masculine (<span class=\"kw-chiffre\">1,5 G / 1 F</span>)</td>\n            <td>Prédominance masculine (<span class=\"kw-chiffre\">3-4 G / 1 F</span>)</td>\n          </tr>\n          <tr>\n            <td>Âge de début</td>\n            <td>Enfance, voire période préscolaire</td>\n            <td>Enfance (<span class=\"kw-alerte\">&lt; 10 ans = mauvais pronostic</span>) ou adolescence ; débute rarement après <span class=\"kw-chiffre\">16 ans</span></td>\n          </tr>\n          <tr>\n            <td>Syndrome clinique</td>\n            <td>Association <strong>intense, persistante, répétitive</strong> de <span class=\"kw-chiffre\">&ge; 4 symptômes</span> : <span class=\"kw-clinique\">opposition et provocation</span> envers <span class=\"kw-clinique\">les</span> adultes ; <span class=\"kw-clinique\">comportements vindicatifs et hostiles</span> ; difficulté à reconnaître ses responsabilités ; <span class=\"kw-clinique\">irritabilité, susceptibilité, accès de colère</span></td>\n            <td>Conduites bafouant <span class=\"kw-clinique\">les</span> <strong>droits fondamentaux d'autrui</strong> et transgressant les normes sociales : <span class=\"kw-clinique\">agressions</span> de personnes ou d'animaux ; <span class=\"kw-clinique\">destructions de biens</span> ; <span class=\"kw-clinique\">vols et fraudes</span> ; <span class=\"kw-clinique\">violations graves des règles</span> (fugues, absentéisme)</td>\n          </tr>\n          <tr>\n            <td>Fréquence requise</td>\n            <td>Enfant <span class=\"kw-chiffre\">&lt; 5 ans</span> : presque tous <span class=\"kw-clinique\">les</span> jours pendant <span class=\"kw-chiffre\">&ge; 6 mois</span><br>Enfant <span class=\"kw-chiffre\">&gt; 5 ans</span> : <span class=\"kw-chiffre\">&ge; 1&times;/semaine</span> pendant <span class=\"kw-chiffre\">&ge; 6 mois</span></td>\n            <td>Syndrome clinique significatif présent dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">12 derniers mois</span> ; <span class=\"kw-def\">critères de</span> retentissement social, familial ou scolaire</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Comorbidités</span></td>\n            <td><span class=\"kw-etio\">TDAH</span> souvent associé ; troubles des apprentissages et de la communication à rechercher systématiquement</td>\n            <td>Souvent précédé d'un <span class=\"kw-etio\">TOP</span> ; <span class=\"kw-etio\">TDAH</span>, troubles des apprentissages ; troubles anxieux et dépressifs plus fréquents qu'en population générale</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Évolution</span></td>\n            <td>Risque fréquent d'<span class=\"kw-clinique\">évolution</span> vers un <span class=\"kw-etio\">TC</span> (lié à la composante opposition/provocation) ; troubles de l'humeur fréquents (liés à l'humeur colérique/irritable)</td>\n            <td>Majoritairement favorable si début à l'adolescence et forme peu sévère ; risque de <span class=\"kw-etio\">personnalité antisociale</span> à l'âge adulte</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Particularités du TC chez <span class=\"kw-clinique\">les</span> filles :</strong> les symptômes d'agressivité physique sont moins fréquents que chez les garçons ; l'<span class=\"kw-clinique\">agressivité relationnelle</span> est fréquente (exclusion sociale d'autrui, colportage de rumeurs).</p>\n      <div class=\"callout callout-danger\"><strong>Gravité.</strong> Le TC expose à un <span class=\"kw-alerte\">risque accru de tentatives de suicide</span> et de suicide, à des comportements délictueux et à des parcours de vie complexes. Facteurs de <strong>mauvais <span class=\"kw-def\">pronostic</span></strong> : <span class=\"kw-alerte\">début précoce (&lt; 10 ans)</span>, <span class=\"kw-alerte\">émotions prosociales limitées</span> (absence de remords/culpabilité, manque d'empathie), <span class=\"kw-alerte\">sévérité des symptômes</span>. La <span class=\"kw-etio\">personnalité antisociale</span> est évoquée en cas de persistance, à l'âge adulte, de comportements agressifs et de transgressions sociales sévères.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 64 — <span class=\"kw-etio\">Trouble bipolaire</span> · 66 — Trouble dépressif · 77 — Addiction aux psychotropes</em></p>","frequence":2}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"cards":[{"i":"0fd0764704dc","n":68,"o":"68-1","u":"Définition","t":"Connaître les caractéristiques de l’adolescence normale","q":"Quels sont les principaux changements observés pendant l'adolescence normale sur les plans psycho-affectif et social ?","a":"<ul><li>Développement de l'<strong>autonomie</strong> et des <strong>contacts sociaux</strong>, avec une influence accrue du <strong>groupe des pairs</strong>.</li><li>Recherche d'<strong>identité et de valeurs</strong>, développement de la personnalité.</li><li>Modifications du <strong>désir sexuel</strong> et du <strong>rapport au corps</strong> : préoccupations fréquentes sur l'apparence physique, marques du corps (tatouages, piercings) fréquentes.</li><li><strong>Hypersensibilité émotionnelle</strong> et sensibilité au rejet.</li><li><strong>Expérimentation</strong>, augmentation des <strong>choix risqués</strong>, moindre sensibilité aux conséquences à long terme des actions.</li></ul>"},{"i":"30be76e232c2","n":68,"o":"68-1","u":"Définition","t":"Connaître les caractéristiques de l’adolescence normale","q":"Comment la maturation cérébrale différentielle explique-t-elle la prise de risque et l'impulsivité physiologiques de l'adolescent ?","a":"<p>L'adolescence est marquée par une <strong>neuro-plasticité</strong> importante avec une maturation cérébrale différentielle :</p><ul><li>Le <strong>système limbique</strong> (sensibilité à la récompense, réactivité émotionnelle) matûre <strong>plus rapidement</strong>.</li><li>Le <strong>cortex préfrontal</strong> (contrôle, inhibition, anticipation des conséquences) matûre <strong>plus tardivement</strong>.</li></ul><p>Ce <strong>décalage de maturation</strong> (limbique précoce versus préfrontal tardif) explique la prise de risque et l'<strong>impulsivité physiologiques</strong> de l'adolescent.</p>"},{"i":"b67c05bcb37b","n":68,"o":"68-1","u":"Définition","t":"Connaître les caractéristiques de l’adolescence normale","q":"Selon l'EDN, quelles sont les caractéristiques générales de la période de l'adolescence sur le plan individuel et social ?","a":"<p>L'adolescence est une période de <strong>maturation individuelle et sociale</strong> liée à un contexte social. Ses contours sont mal définis et évolutifs, avec un âge d'accès à l'autonomie qui ne cesse de s'accroître. Les modifications observées résultent de multiples facteurs <strong>biologiques, psycho-affectifs et sociaux</strong>.</p>"},{"i":"5e9103b0db7c","n":68,"o":"68-2","u":"Définition","t":"Connaître la définition des troubles du comportement de l’enfant et de l’adolescent","q":"Quelles sont les deux entités principales recouvrant les troubles du comportement de l'enfant et de l'adolescent ?","a":"<ul><li>Le <strong>trouble oppositionnel avec provocation (TOP)</strong>.</li><li>Le <strong>trouble des conduites (TC)</strong>.</li></ul>"},{"i":"617925904dc3","n":68,"o":"68-2","u":"Définition","t":"Connaître la définition des troubles du comportement de l’enfant et de l’adolescent","q":"Quelle est la définition générale des troubles du comportement de l'enfant et de l'adolescent ?","a":"<p>Les troubles du comportement de l'enfant et de l'adolescent, également appelés <strong>troubles externalisés</strong>, recouvrent des comportements perturbateurs dirigés vers l'extérieur comme l'opposition, la provocation, l'agression et la transgression. Ils s'opposent aux troubles internalisés (anxiété, dépression).</p>"},{"i":"65e6839f05ac","n":68,"o":"68-2","u":"Définition","t":"Connaître la définition des troubles du comportement de l’enfant et de l’adolescent","q":"Comment différencier un trouble du comportement externalisé d'un comportement perturbateur transitoire chez l'enfant ou l'adolescent ?","a":"<p>Il est crucial de distinguer les troubles du comportement externalisés constitués des <strong>troubles du comportement transitoires</strong>. Ces derniers sont réactionnels, passagers et surviennent en contexte de stress, ne constituant pas un trouble externalisé établi.</p>"},{"i":"04f4fdd2d239","n":68,"o":"68-4","u":"Diagnostic","t":"Connaître le diagnostic positif des troubles du comportement de l’enfant et de l’adolescent","q":"Sur quels critères le diagnostic des troubles du comportement de l'enfant et de l'adolescent repose-t-il ?","a":"<p>Le diagnostic des troubles du comportement repose <strong>exclusivement sur des critères cliniques</strong>.</p>"},{"i":"0e6922e90301","n":68,"o":"68-4","u":"Diagnostic","t":"Connaître le diagnostic positif des troubles du comportement de l’enfant et de l’adolescent","q":"Quel est le piège diagnostique à éviter concernant l'auto-évaluation par l'enfant dans le cadre des troubles du comportement (TOP/TC) ?","a":"<p>L'auto-évaluation par l'enfant <strong>n'est pas toujours fiable</strong> pour les symptômes de TOP/TC et ne doit <strong>jamais être la seule source</strong> d'information.</p>"},{"i":"1c84feeec81a","n":68,"o":"68-4","u":"Diagnostic","t":"Connaître le diagnostic positif des troubles du comportement de l’enfant et de l’adolescent","q":"Quelle est la fréquence requise des symptômes pour poser le diagnostic de Trouble Oppositionnel avec Provocation (TOP) chez l'enfant de moins de 5 ans et de plus de 5 ans ?","a":"<ul><li>Pour les enfants <strong>de moins de 5 ans</strong> : les symptômes doivent être présents <strong>presque tous les jours</strong> pendant <strong>au moins 6 mois</strong>.</li><li>Pour les enfants <strong>de plus de 5 ans</strong> : les symptômes doivent être présents <strong>au moins une fois par semaine</strong> pendant <strong>au moins 6 mois</strong>.</li></ul>"},{"i":"39bbe070bf19","n":68,"o":"68-4","u":"Diagnostic","t":"Connaître le diagnostic positif des troubles du comportement de l’enfant et de l’adolescent","q":"Quels sont les différents types de troubles du comportement distingués par le diagnostic et leurs caractéristiques cliniques principales ?","a":"<ul><li><strong>Trouble Oppositionnel avec Provocation (TOP)</strong> : Association intense, persistante, répétitive de <strong>plus de 4 symptômes</strong> incluant opposition, provocation, comportements vindicatifs/hostiles, difficulté à reconnaître ses responsabilités, irritabilité, susceptibilité, accès de colère.</li><li><strong>Trouble des Conduites (TC)</strong> : Conduites bafouant les droits fondamentaux d'autrui et transgressant les normes sociales (agressions de personnes/animaux, destructions de biens, vols/fraudes, violations graves des règles comme les fugues ou l'absentéisme).</li></ul>"},{"i":"512c0b455ed7","n":68,"o":"68-4","u":"Diagnostic","t":"Connaître le diagnostic positif des troubles du comportement de l’enfant et de l’adolescent","q":"Quels sont les facteurs de mauvais pronostic du Trouble des Conduites (TC) ?","a":"<ul><li>Début <strong>précoce (< 10 ans)</strong>.</li><li>Présence d'<strong>émotions prosociales limitées</strong> (absence de remords/culpabilité, manque d'empathie).</li><li><strong>Sévérité des symptômes</strong>.</li></ul>"},{"i":"724f29eaf8e3","n":68,"o":"68-4","u":"Diagnostic","t":"Connaître le diagnostic positif des troubles du comportement de l’enfant et de l’adolescent","q":"Quelle est la particularité du Trouble des Conduites (TC) chez les filles par rapport aux garçons ?","a":"<p>Chez les filles, les symptômes d'agressivité physique sont <strong>moins fréquents</strong> que chez les garçons. L'<strong>agressivité relationnelle</strong> (exclusion sociale d'autrui, colportage de rumeurs) est en revanche fréquente.</p>"},{"i":"a4a578dc9875","n":68,"o":"68-4","u":"Diagnostic","t":"Connaître le diagnostic positif des troubles du comportement de l’enfant et de l’adolescent","q":"Quels sont les éléments de la démarche diagnostique commune aux troubles du comportement de l'enfant et de l'adolescent ?","a":"<ul><li><strong>Histoire</strong> : Reconstituer l'histoire développementale du patient.</li><li><strong>Symptomatologie</strong> : Passée et actuelle, ne correspondant pas au développement normal attendu.</li><li><strong>Sources d'information</strong> : Multiples (parents, professeurs, éducateurs, enfant/adolescent lui-même).</li><li><strong>Retentissement</strong> : Dans <strong>au moins 2 domaines</strong> de vie (familial, scolaire, activités extra-scolaires, social).</li><li><strong>Durée</strong> : Évoluant depuis <strong>plus de 6 mois</strong>.</li><li><strong>Âge de début</strong> : Pendant l'enfance ou l'adolescence.</li></ul>"},{"i":"f34f216967bd","n":68,"o":"68-4","u":"Diagnostic","t":"Connaître le diagnostic positif des troubles du comportement de l’enfant et de l’adolescent","q":"Quelles sont les principales comorbidités associées au Trouble Oppositionnel avec Provocation (TOP) et au Trouble des Conduites (TC) ?","a":"<ul><li><strong>TOP</strong> : Le <strong>TDAH</strong> est souvent associé ; des troubles des apprentissages et de la communication doivent être recherchés systématiquement.</li><li><strong>TC</strong> : Souvent précédé d'un <strong>TOP</strong> ; <strong>TDAH</strong>, troubles des apprentissages ; troubles anxieux et dépressifs sont plus fréquents.</li></ul>"}]};